# Non-US productions that must NOT carry the "Hollywood" origin tag
# (SCHEMA.md: Hollywood = US studio system; others use a country tag).
REGION_TAG: dict[str, str] = {
    "The Intouchables": "French",
    "Another Round": "Danish",
    "Broker": "Korean",
    "Athena": "French",
    "Kneecap": "Irish",
    "Flow": "Latvian",
    "Sing Street": "Irish",
    "Talk to Me": "Australian",
    "The Stranger": "Australian",
    "Memoir of a Snail": "Australian",
    "Belfast": "British",
    "Living": "British",
    "Last Night in Soho": "British",
    "Paddington 2": "British",
    "The Gentlemen": "British",
    "Pinocchio": "Mexican",
    "The Green Knight": "British",
    "The Apprentice": "Canadian",
}


def _norm(s: str) -> str:
    """Normalize a title for dedup: lowercase, strip punctuation, collapse spaces."""
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]", "", s.lower())).strip()


def _slug(s: str) -> str:
    """Kebab-case slug for ids."""
    return re.sub(r"-+", "-", re.sub(r"[^a-z0-9]+", "-", s.lower())).strip("-")


def main() -> None:
    films_path = Path("app/src/main/assets/topics/films.json")
    existing = json.loads(films_path.read_text(encoding="utf-8"))
    existing_ids = {t["id"] for t in existing}
    # Compare by title-without-year so new entries dedupe against existing ones.
    existing_norms = {_norm(t["name"].rsplit(" (", 1)[0]): t for t in existing}

    added: list[dict] = []
    skipped: list[str] = []
    for (title, year, director, g1, g2, runtime, tier, teaser, instruction) in FILMS:
        if not teaser or not instruction:
            skipped.append(f"{title} ({year}) — blank teaser/instruction placeholder")
            continue
        key = _norm(title)
        if key in existing_norms:
            skipped.append(f"{title} ({year}) — already in films.json")
            continue
        base = f"film-{_slug(title)}-{year}"
        tid = base
        n = 2
        while tid in existing_ids:
            tid = f"{base}-{n}"
            n += 1
        existing_ids.add(tid)
        decade = f"{year // 10 * 10}s"
        added.append({
            "id": tid,
            "categoryId": "FILMS",
            "subtype": "Film",
            "name": f"{title} ({year})",
            "teaser": teaser,
            "imageUrl": "",
            "byline": director,
            "exploreAction": {
                "verb": "Watch",
                "targetName": f"{title} ({year}) end-to-end",
                "durationMinutes": runtime,
                "instruction": instruction,
            },
            "tags": [g1, g2, decade, REGION_TAG.get(title, "Hollywood")],
            "tier": tier,
        })

    merged = existing + added
    # indent=2 + ensure_ascii=False matches the file's existing formatting.
    films_path.write_text(json.dumps(merged, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"existing: {len(existing)}  added: {len(added)}  skipped: {len(skipped)}  total: {len(merged)}")
    for s in skipped:
        print(f"  skip: {s}")


if __name__ == "__main__":
    main()

